files./etc/nginx/nginx.conf:
worker_processes 1;
pid /tmp/nl-edge-nginx.pid;
error_log stderr warn;
events {}
http {
  access_log off;
  client_body_temp_path /tmp/nl-edge-nginx-body;
  proxy_temp_path /tmp/nl-edge-nginx-proxy;
  fastcgi_temp_path /tmp/nl-edge-nginx-fastcgi;
  uwsgi_temp_path /tmp/nl-edge-nginx-uwsgi;
  scgi_temp_path /tmp/nl-edge-nginx-scgi;
  upstream app { server 198.18.233.11:8080; server 198.18.233.12:8080; server 198.18.233.13:8080; }
  # :8000 the edge overwrites X-Forwarded-For with the address it saw
  server { listen 8000; location / { proxy_pass http://app; proxy_set_header X-Forwarded-For $remote_addr; } }
  # :8001 the edge appends to whatever the client sent
  server { listen 8001; location / { proxy_pass http://app; proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for; } }
}
